fields.InputDefinition:
{
  "goal": "Open the application switcher dropdown next to the logo and switch to Data Explorer, then open the Queries section. Then perform these sub-actions IN ORDER, and as you complete each set \"checkpointReached\" to the exact checkpoint name shown: (1) query-status-chips — the left query panel shows a row of status filter chips (Approved, Pending, Rejected, Expired) with count badges; click 'Pending' to toggle it on and 'Approved' to toggle it off, and confirm the visible query tree responds to the chip toggles (the shown queries change, or a valid empty tree appears); (2) query-expand-collapse — in the panel header find the 'Expand all' (open-folder) and 'Collapse all' (folder) toolbar icons; click 'Expand all' to reveal queries under the category folders, then 'Collapse all' to collapse them back (if there are no nested categories, the buttons present + a stable/empty tree is acceptable); (3) query-panel-resize — drag the vertical resize handle between the left query tree panel and the right query viewer to change the left panel width, then release, and confirm the left panel visibly changes width and holds it. Keep going until all sub-actions are done. Pages can take 10-30s to load in this resource-constrained environment — wait, don't navigate away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "finalUrlPattern": "^http://localhost:4200",
  "minConfidence": 0.7,
  "maxSteps": 45,
  "checkpoints": [
    {
      "name": "query-status-chips",
      "instruction": "toggle status filter chips and see the tree respond",
      "visualCriteria": [
        "A status filter chip bar with Approved/Pending/Rejected/Expired chips and count badges is visible above the query tree, and toggling a status chip on/off visibly changes which queries appear (chips gain/lose their highlighted state) or a valid empty state appears when no queries match"
      ]
    },
    {
      "name": "query-expand-collapse",
      "instruction": "expand-all then collapse-all the category tree",
      "visualCriteria": [
        "'Expand all' and 'Collapse all' toolbar controls are present in the query panel header, and clicking Expand all expands the category folders to reveal queries and Collapse all collapses them back — or, if no nested categories exist, a valid empty/flat-tree state renders without error"
      ]
    },
    {
      "name": "query-panel-resize",
      "instruction": "drag the resize handle to change the left panel width",
      "visualCriteria": [
        "A vertical resize handle/grip exists between the query tree panel and the viewer, and dragging it visibly changes the left query panel's width and it holds the new width after release"
      ]
    }
  ]
}
